def create_operation_rows(apps, schema_editor):
    """Precreate one reservation row per existing cabinet.

    The plugin precreates a ``CabinetOperation`` row for every cabinet so that
    reservation state transitions always have a row to lock. Cabinets created
    after this migration are handled by the model ``post_save`` receiver.
    """
    Cabinet = apps.get_model('storage_layout', 'Cabinet')
    CabinetOperation = apps.get_model('storage_layout', 'CabinetOperation')

    existing = set(
        CabinetOperation.objects.values_list('cabinet_id', flat=True)
    )

    CabinetOperation.objects.bulk_create(
        [
            CabinetOperation(cabinet_id=cabinet.pk)
            for cabinet in Cabinet.objects.all()
            if cabinet.pk not in existing
        ]
    )


def remove_operation_rows(apps, schema_editor):
    """Reverse the operation row creation."""
    CabinetOperation = apps.get_model('storage_layout', 'CabinetOperation')
    CabinetOperation.objects.all().delete()


